<?php include 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $id=(int)$_POST['patient_id']; $name=trim($_POST['name']); $age=(int)$_POST['age']; $gender=$_POST['gender']; $addr=trim($_POST['address']); if($id<=0||$name==''||$age<=0||!in_array($gender,['Male','Female','Other'])||$addr==''){$msg='Enter valid patient details';} else {$stmt=mysqli_prepare($conn,'INSERT INTO patients VALUES(?,?,?,?,?)'); mysqli_stmt_bind_param($stmt,'isiss',$id,$name,$age,$gender,$addr); if(!mysqli_stmt_execute($stmt)) $msg='Duplicate Patient ID';}}
$res=mysqli_query($conn,'SELECT * FROM patients ORDER BY patient_id'); ?>
<!DOCTYPE html><html><head><title>Q18 Patients</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Hospital Patient Registration</h1><form method="post"><input name="patient_id" placeholder="Patient ID"><input name="name" placeholder="Name"><input name="age" placeholder="Age"><select name="gender"><option>Male</option><option>Female</option><option>Other</option></select><textarea name="address" placeholder="Address"></textarea><button>Register</button></form><p class="error"><?php echo $msg; ?></p><input id="searchBox" placeholder="Search table"><table><thead><tr><th>ID</th><th>Name</th><th>Age</th><th>Gender</th><th>Address</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($res)){ ?><tr><td><?php echo $r['patient_id']; ?></td><td><?php echo $r['name']; ?></td><td><?php echo $r['age']; ?></td><td><?php echo $r['gender']; ?></td><td><?php echo $r['address']; ?></td></tr><?php } ?></tbody></table></div><script src="script.js"></script></body></html>
